def compute_model_placement(gpu_num, models):
    """Place high standalone-pressure models first, then make KVPR-reducing feasible moves."""
    def pressure(load, memory):
        return load / memory if memory > 0 else float("inf")

    placement = {g: [] for g in range(gpu_num)}
    memory, load = [GPU_MEM_SIZE] * gpu_num, [0.0] * gpu_num
    ordered = sorted(
        models,
        key=lambda m: pressure(m.req_rate / m.slo, GPU_MEM_SIZE - m.model_size),
        reverse=True,
    )

    for model in ordered:
        size, weight = model.model_size, model.req_rate / model.slo
        choices = [g for g in range(gpu_num) if memory[g] >= size]
        if not choices:
            raise ValueError("Models cannot fit in the available GPU memory")
        g = min(choices, key=lambda g: pressure(load[g] + weight, memory[g] - size))
        placement[g].append(model)
        memory[g] -= size
        load[g] += weight

    for _ in range(min(len(models), gpu_num * 2)):
        best = max(pressure(load[g], memory[g]) for g in range(gpu_num))
        move = None
        for source in range(gpu_num):
            if pressure(load[source], memory[source]) < best:
                continue
            for model in placement[source]:
                size, weight = model.model_size, model.req_rate / model.slo
                for target in range(gpu_num):
                    if source == target or memory[target] < size:
                        continue
                    value = max(
                        pressure(
                            load[g] + (weight if g == target else -weight if g == source else 0),
                            memory[g] - (size if g == target else -size if g == source else 0),
                        )
                        for g in range(gpu_num)
                    )
                    if value < best:
                        best, move = value, (source, target, model, size, weight)
        if move is None:
            break
        source, target, model, size, weight = move
        placement[source].remove(model)
        placement[target].append(model)
        memory[source] += size
        memory[target] -= size
        load[source] -= weight
        load[target] += weight

    return placement

